use strict; use warnings; use Math::Trig;
sub triangulate {
  my ($pts)=@_;
  my $n=@$pts;
  return () if $n<3;
  my @prev = map { ($_-1+$n)%$n } 0..$n-1;
  my @next = map { ($_+1)%$n } 0..$n-1;
  my @alive = (1)x$n;
  my $cnt = $n;
  my @out;
  my $area=0;
  for my $i (0..$n-1) {
    my $j = ($i+1)%$n;
    $area += $pts->[$i][0]*$pts->[$j][1] - $pts->[$j][0]*$pts->[$i][1];
  }
  my $ccw = $area > 0;
  my $ear = $n-1;
  my $stop = $n-1;
  my $iter=0;
  while ($cnt > 2) {
    die "loop" if ++$iter > 10000;
    my $p = $prev[$ear];
    my $q = $next[$ear];
    if (is_ear($ear,$p,$q,$pts,\@prev,\@next,\@alive,$ccw)) {
      push @out, $p,$ear,$q;
      $next[$p] = $q;
      $prev[$q] = $p;
      $alive[$ear]=0;
      $cnt--;
      $ear = $next[$q];
      $stop = $ear;
      next;
    }
    $ear = $q;
    if ($ear == $stop) { last; }
  }
  return @out;
}
sub area2 {
  my ($a,$b,$c)=@_;
  return ($b->[0]-$a->[0])*($c->[1]-$a->[1]) - ($b->[1]-$a->[1])*($c->[0]-$a->[0]);
}
sub point_in_tri {
  my ($p,$a,$b,$c,$ccw)=@_;
  my $ab = area2($a,$b,$p);
  my $bc = area2($b,$c,$p);
  my $ca = area2($c,$a,$p);
  my $eps = 1e-12;
  if ($ccw) {
    return $ab >= -$eps && $bc >= -$eps && $ca >= -$eps;
  } else {
    return $ab <= $eps && $bc <= $eps && $ca <= $eps;
  }
}
sub is_ear {
  my ($i,$p,$q,$pts,$prev,$next,$alive,$ccw)=@_;
  my $a = $pts->[$p]; my $b = $pts->[$i]; my $c = $pts->[$q];
  my $cross = area2($a,$b,$c);
  my $eps = 1e-12;
  return 0 if $ccw ? $cross <= $eps : $cross >= -$eps;
  my $j = $next->[$q];
  while ($j != $p) {
    if ($alive->[$j]) {
      # only reflex vertices can be inside for simple polygon, but skip optimization
      if ($j != $p && $j != $i && $j != $q && point_in_tri($pts->[$j],$a,$b,$c,$ccw)) {
        return 0;
      }
    }
    $j = $next->[$j];
  }
  return 1;
}
