  my ($n)=@_;
  my @pts;
  for my $i (0..$n-1) {
    my $a1 = 2*pi*$i/$n;
    my $a2 = 2*pi*($i+0.5)/$n;
    push @pts, [cos($a1), sin($a1)];
    push @pts, [0.7*cos($a2), 0.7*sin($a2)];
  }
  return @pts;
}
for my $n (0..15) {
  my @pts = gear($n) if $n>0;
  my @tri = triangulate(\@pts);
  print "$n @tri\n";
}
